import { Category, SubCategory, Lyric, User, UserRole } from './types';
import { INITIAL_CATEGORIES, INITIAL_SUBCATEGORIES, INITIAL_LYRICS } from './constants';

const DB_KEYS = {
  CATEGORIES: 'islamic_poetry_categories_v2',
  SUBCATEGORIES: 'islamic_poetry_subcategories_v2',
  LYRICS: 'islamic_poetry_lyrics_v2',
  USERS: 'islamic_poetry_users_v2',
  SESSION: 'islamic_poetry_session_v2'
};

export const db = {
  getCategories: (): Category[] => {
    const data = localStorage.getItem(DB_KEYS.CATEGORIES);
    if (!data) {
      localStorage.setItem(DB_KEYS.CATEGORIES, JSON.stringify(INITIAL_CATEGORIES));
      return INITIAL_CATEGORIES;
    }
    return JSON.parse(data).sort((a: Category, b: Category) => a.serial - b.serial);
  },

  saveCategory: (category: Category) => {
    const categories = db.getCategories();
    const index = categories.findIndex(c => c.id === category.id);
    if (index > -1) {
      categories[index] = category;
    } else {
      categories.push(category);
    }
    localStorage.setItem(DB_KEYS.CATEGORIES, JSON.stringify(categories));
  },

  deleteCategory: (id: string) => {
    const categories = db.getCategories().filter(c => c.id !== id);
    localStorage.setItem(DB_KEYS.CATEGORIES, JSON.stringify(categories));
    // Cascade delete subcategories and lyrics is usually good but we'll leave for safety
  },

  getSubCategories: (categoryId?: string): SubCategory[] => {
    const data = localStorage.getItem(DB_KEYS.SUBCATEGORIES);
    let subs: SubCategory[] = data ? JSON.parse(data) : INITIAL_SUBCATEGORIES;
    if (!data) localStorage.setItem(DB_KEYS.SUBCATEGORIES, JSON.stringify(INITIAL_SUBCATEGORIES));

    if (categoryId) {
      subs = subs.filter(s => s.categoryId === categoryId);
    }
    return subs.sort((a, b) => a.serial - b.serial);
  },

  saveSubCategory: (sub: SubCategory) => {
    const subs = db.getSubCategories();
    const index = subs.findIndex(s => s.id === sub.id);
    if (index > -1) {
      subs[index] = sub;
    } else {
      subs.push(sub);
    }
    localStorage.setItem(DB_KEYS.SUBCATEGORIES, JSON.stringify(subs));
  },

  deleteSubCategory: (id: string) => {
    const subs = db.getSubCategories().filter(s => s.id !== id);
    localStorage.setItem(DB_KEYS.SUBCATEGORIES, JSON.stringify(subs));
  },

  getLyrics: (subCategoryId?: string): Lyric[] => {
    const data = localStorage.getItem(DB_KEYS.LYRICS);
    let lyrics: Lyric[] = data ? JSON.parse(data) : INITIAL_LYRICS;
    if (!data) localStorage.setItem(DB_KEYS.LYRICS, JSON.stringify(INITIAL_LYRICS));

    if (subCategoryId) {
      lyrics = lyrics.filter(l => l.subCategoryId === subCategoryId);
    }
    return lyrics.sort((a, b) => a.serial - b.serial);
  },

  saveLyric: (lyric: Lyric) => {
    const lyrics = db.getLyrics();
    const index = lyrics.findIndex(l => l.id === lyric.id);
    if (index > -1) {
      lyrics[index] = lyric;
    } else {
      lyrics.push(lyric);
    }
    localStorage.setItem(DB_KEYS.LYRICS, JSON.stringify(lyrics));
  },

  deleteLyric: (id: string) => {
    const lyrics = db.getLyrics().filter(l => l.id !== id);
    localStorage.setItem(DB_KEYS.LYRICS, JSON.stringify(lyrics));
  },

  getCurrentUser: (): User | null => {
    const session = localStorage.getItem(DB_KEYS.SESSION);
    return session ? JSON.parse(session) : null;
  },

  login: (username: string): User => {
    const user: User = { id: 'admin-1', username, role: UserRole.ADMIN };
    localStorage.setItem(DB_KEYS.SESSION, JSON.stringify(user));
    return user;
  },

  logout: () => {
    localStorage.removeItem(DB_KEYS.SESSION);
  }
};

