                placeholder="ذیلی عنوان" 
                value={subCatForm.name || ''} 
                onChange={e => setSubCatForm({...subCatForm, name: e.target.value})}
              />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">Serial Number</label>
              <input 
                type="number" 
                className="p-3 border border-[#5D4037]/30 text-right urdu-text bg-white/60" 
                placeholder="ترتیب نمبر" 
                value={subCatForm.serial || ''} 
                onChange={e => setSubCatForm({...subCatForm, serial: parseInt(e.target.value)})}
              />
            </div>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setView('DASHBOARD')} className="flex-1 bg-gray-400 text-white p-3 font-bold text-xs uppercase tracking-widest">منسوخ</button>
            <button onClick={saveSubCategory} className="flex-1 bg-[#5D4037] text-white p-3 font-bold text-xs uppercase tracking-widest">محفوظ کریں</button>
          </div>
        </div>
      )}

      {view === 'LYRIC_FORM' && (
        <div className="flex flex-col gap-6 animate-fadeIn">
          <h3 className="text-xl font-bold text-center urdu-text border-b border-[#5D4037]/20 pb-2">کلام کی تفصیلات</h3>
          <div className="flex flex-col gap-4">
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">Parent Category (Filter)</label>
              <select 
                className="p-3 border border-[#5D4037]/30 text-right urdu-text bg-white/60"
                value={selectedParentCatId}
                onChange={e => setSelectedParentCatId(e.target.value)}
              >
                <option value="">عنوان منتخب کریں</option>
                {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
