            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">Sub-Category</label>
              <select 
                disabled={!selectedParentCatId}
                className={`p-3 border border-[#5D4037]/30 text-right urdu-text bg-white/60 ${!selectedParentCatId ? 'opacity-50' : ''}`}
                value={lyricForm.subCategoryId || ''}
                onChange={e => setLyricForm({...lyricForm, subCategoryId: e.target.value})}
              >
                <option value="">ذیلی عنوان منتخب کریں</option>
                {filteredSubCatsForForm.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">Lyric Title</label>
              <input 
                className="p-3 border border-[#5D4037]/30 text-right urdu-text bg-white/60" 
                placeholder="کلام کا عنوان" 
                value={lyricForm.title || ''} 
                onChange={e => setLyricForm({...lyricForm, title: e.target.value})}
              />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">Poetry Content</label>
              <textarea 
                className="p-3 border border-[#5D4037]/30 text-right h-48 urdu-text bg-white/60" 
                placeholder="شاعری یہاں لکھیں..." 
                value={lyricForm.content || ''} 
                onChange={e => setLyricForm({...lyricForm, content: e.target.value})}
              />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">Serial Number</label>
              <input 
                type="number" 
                className="p-3 border border-[#5D4037]/30 text-right urdu-text bg-white/60" 
                placeholder="ترتیب نمبر" 
                value={lyricForm.serial || ''} 
                onChange={e => setLyricForm({...lyricForm, serial: parseInt(e.target.value)})}
              />
            </div>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setView('DASHBOARD')} className="flex-1 bg-gray-400 text-white p-3 font-bold text-xs uppercase tracking-widest">منسوخ</button>
            <button onClick={saveLyric} className="flex-1 bg-[#5D4037] text-white p-3 font-bold text-xs uppercase tracking-widest">محفوظ کریں</button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect } from 'react';
import { HashRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import { Layout } from './components/Layout';
import { Home } from './components/Home';
import { Cover } from './components/Cover';
import { CategoryDetail } from './components/CategoryDetail';
import { SubCategoryDetail } from './components/SubCategoryDetail';
import { LyricView } from './components/LyricView';
import { Admin } from './components/Admin';

// ScrollToTop component to reset scroll position on route changes
const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

const App: React.FC = () => {
  return (
    <Router>
      <ScrollToTop />
      <Layout>
        <Routes>
          <Route path="/" element={<Cover />} />
          <Route path="/categories" element={<Home />} />
          <Route path="/category/:id" element={<CategoryDetail />} />
          <Route path="/subcategory/:id" element={<SubCategoryDetail />} />
          <Route path="/lyric/:id" element={<LyricView />} />
          <Route path="/admin" element={<Admin />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

