  const handleDeleteSubCategory = (id: string, name: string) => {
    if (window.confirm(`کیا آپ واقعی ذیلی عنوان "${name}" کو حذف کرنا چاہتے ہیں؟`)) {
      db.deleteSubCategory(id);
      refreshData();
    }
