      db.saveCategory({
        id: catForm.id || Math.random().toString(36).substr(2, 9),
        name: catForm.name,
        serial: Number(catForm.serial) || (categories.length + 1)
      } as Category);
      setCatForm({});
      setView('DASHBOARD');
      refreshData();
    }
