          <input type="password" placeholder="پاس ورڈ" className="p-3 border border-[#5D4037]/30 bg-white/60 text-right urdu-text rounded-sm focus:outline-none focus:border-[#5D4037]" required />
          <button type="submit" className="bg-[#5D4037] text-white p-4 font-bold rounded-sm shadow-md active:scale-95 transition-transform">لاگ ان کریں</button>
        </form>
