export interface Category {
  id: string;
  name: string; // Urdu Name
  serial: number;
  imageUrl?: string; // Base64 or URL
}

export interface SubCategory {
  id: string;
  categoryId: string;
  name: string;
  serial: number;
}

export interface Lyric {
  id: string;
  subCategoryId: string;
  title: string;
  content: string; // The poetry lines
  serial: number;
}

export enum UserRole {
  ADMIN = 'ADMIN',
  EDITOR = 'EDITOR'
}

export interface User {
  id: string;
  username: string;
  role: UserRole;
}

import React, { useEffect, useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { db } from '../db';
import { Category, Lyric } from '../types';
import { COLORS } from '../constants';

export const Home: React.FC = () => {
  const [categories, setCategories] = useState<Category[]>(() => db.getCategories());
  const [allLyrics, setAllLyrics] = useState<Lyric[]>(() => db.getLyrics());
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    setCategories(db.getCategories());
    setAllLyrics(db.getLyrics());
  }, []);

  const filteredLyrics = useMemo(() => {
    if (!searchQuery.trim()) return [];
    const query = searchQuery.toLowerCase();
    return allLyrics.filter(lyric => 
      lyric.title.toLowerCase().includes(query) || 
      lyric.content.toLowerCase().includes(query)
    );
  }, [searchQuery, allLyrics]);

  return (
    <div className="flex flex-col items-center w-full space-y-6">
      <div className="text-center space-y-1">
        <h2 className="text-xl font-bold urdu-text" style={{ color: COLORS.GREEN }}>
          فہرستِ عنوانات
        </h2>
        <div className="w-16 h-0.5 bg-[#5D4037] mx-auto opacity-20"></div>
      </div>

      <div className="w-full relative px-2">
        <input
          type="text"
          placeholder="کلام تلاش کریں..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-full p-2 pr-10 border border-[#5D4037]/30 bg-white/40 text-right urdu-text focus:outline-none focus:border-[#5D4037] transition-all rounded-sm placeholder:opacity-40 text-sm"
          dir="rtl"
        />
        <div className="absolute left-5 top-1/2 -translate-y-1/2 pointer-events-none opacity-40">
          <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/></svg>
        </div>
      </div>

      {searchQuery.trim() ? (
        <div className="w-full animate-fadeIn">
          <h2 className="text-[10px] font-bold mb-3 border-b border-[#5D4037]/10 pb-1 text-[#5D4037] uppercase tracking-wider">نتائج ({filteredLyrics.length})</h2>
          <div className="flex flex-col space-y-1 max-h-[55vh] overflow-y-auto pr-1">
            {filteredLyrics.map(lyric => (
              <Link
                key={lyric.id}
                to={`/lyric/${lyric.id}`}
                className="flex items-center justify-between border-b border-[#5D4037]/5 p-2 active:bg-[#5D4037]/5 rounded-sm"
              >
                <span className="text-lg urdu-text text-right text-[#5D4037]">{lyric.title}</span>
                <span className="text-[9px] uppercase font-bold text-[#5D4037]/40">فتح</span>
              </Link>
            ))}
            {filteredLyrics.length === 0 && <div className="text-center py-10 opacity-50 urdu-text text-sm">نتیجہ نہیں ملا</div>}
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-3 w-full">
          {categories.map((cat) => (
            <Link
              key={cat.id}
              to={`/category/${cat.id}`}
              className="group flex flex-col items-center justify-center py-4 px-3 text-center border border-[#5D4037]/20 bg-[#F9F7E8] active:bg-[#5D4037] active:text-[#F5F5DC] transition-all rounded-sm shadow-sm overflow-hidden"
            >
              {cat.imageUrl && (
                <div className="w-full h-20 mb-3 overflow-hidden rounded-sm border border-[#5D4037]/10">
                  <img src={cat.imageUrl} alt={cat.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                </div>
              )}
              <span className="text-[10px] font-bold opacity-30 mb-1">{cat.serial}</span>
              <span className="text-lg urdu-text font-bold leading-tight">{cat.name}</span>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
};

