  const [catForm, setCatForm] = useState<Partial<Category>>({});
  const [subCatForm, setSubCatForm] = useState<Partial<SubCategory>>({});
  const [lyricForm, setLyricForm] = useState<Partial<Lyric>>({});
  const [selectedParentCatId, setSelectedParentCatId] = useState<string>('');

  const t = translations[lang];

  useEffect(() => {
    const current = db.getCurrentUser();
    if (current) {
      setUser(current);
      setView('DASHBOARD');
      refreshData();
    }
  }, []);

  const refreshData = () => {
    setCategories(db.getCategories());
    setSubCategories(db.getSubCategories());
    setLyrics(db.getLyrics());
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setUser(db.login('Admin User'));
    setView('DASHBOARD');
    refreshData();
  };

  const validateSerial = (val: any, list: {serial: number, id?: string}[], currentId?: string): number => {
    let num = parseInt(val) || (list.length + 1);
    if (num < 1) num = 1;
    return num;
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setCatForm(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const saveCategory = () => {
    if (catForm.name) {
      db.saveCategory({
        id: catForm.id || Math.random().toString(36).substr(2, 9),
        name: catForm.name,
        serial: validateSerial(catForm.serial, categories, catForm.id),
        imageUrl: catForm.imageUrl
      } as Category);
      setCatForm({});
      setView('DASHBOARD');
      refreshData();
    }
  };

  const saveSubCategory = () => {
    if (subCatForm.name && subCatForm.categoryId) {
      db.saveSubCategory({
        id: subCatForm.id || Math.random().toString(36).substr(2, 9),
        categoryId: subCatForm.categoryId,
        name: subCatForm.name,
        serial: validateSerial(subCatForm.serial, subCategories.filter(s => s.categoryId === subCatForm.categoryId), subCatForm.id)
      } as SubCategory);
      setSubCatForm({});
      setView('DASHBOARD');
      refreshData();
    }
  };

  const saveLyric = () => {
    if (lyricForm.title && lyricForm.subCategoryId && lyricForm.content) {
      db.saveLyric({
        id: lyricForm.id || Math.random().toString(36).substr(2, 9),
        title: lyricForm.title,
        subCategoryId: lyricForm.subCategoryId,
        content: lyricForm.content,
        serial: validateSerial(lyricForm.serial, lyrics.filter(l => l.subCategoryId === lyricForm.subCategoryId), lyricForm.id)
      } as Lyric);
      setLyricForm({});
      setView('DASHBOARD');
      refreshData();
    }
  };

  // Drag and Drop logic
  const onDragStart = (e: React.DragEvent, id: string) => {
    e.dataTransfer.setData("id", id);
  };

  const onDrop = (e: React.DragEvent, targetId: string) => {
    const draggedId = e.dataTransfer.getData("id");
    if (draggedId === targetId) return;

    if (activeTab === 'CATS') {
      const list = [...categories];
      const draggedIdx = list.findIndex(i => i.id === draggedId);
      const targetIdx = list.findIndex(i => i.id === targetId);
      const [moved] = list.splice(draggedIdx, 1);
      list.splice(targetIdx, 0, moved);
      list.forEach((item, i) => {
        item.serial = i + 1;
        db.saveCategory(item);
      });
    } else if (activeTab === 'SUBCATS') {
      const draggedItem = subCategories.find(s => s.id === draggedId);
      const targetItem = subCategories.find(s => s.id === targetId);
      if (draggedItem?.categoryId !== targetItem?.categoryId) return;
      const list = subCategories.filter(s => s.categoryId === draggedItem.categoryId);
      const draggedIdx = list.findIndex(i => i.id === draggedId);
      const targetIdx = list.findIndex(i => i.id === targetId);
      const [moved] = list.splice(draggedIdx, 1);
      list.splice(targetIdx, 0, moved);
      list.forEach((item, i) => {
        item.serial = i + 1;
        db.saveSubCategory(item);
      });
    } else if (activeTab === 'LYRICS') {
      const draggedItem = lyrics.find(l => l.id === draggedId);
      const targetItem = lyrics.find(l => l.id === targetId);
      if (draggedItem?.subCategoryId !== targetItem?.subCategoryId) return;
      const list = lyrics.filter(l => l.subCategoryId === draggedItem.subCategoryId);
      const draggedIdx = list.findIndex(i => i.id === draggedId);
      const targetIdx = list.findIndex(i => i.id === targetId);
      const [moved] = list.splice(draggedIdx, 1);
      list.splice(targetIdx, 0, moved);
      list.forEach((item, i) => {
        item.serial = i + 1;
        db.saveLyric(item);
      });
    }
    refreshData();
  };

  const filteredData = useMemo(() => {
    const q = searchTerm.toLowerCase();
    if (activeTab === 'CATS') return categories.filter(c => c.name.toLowerCase().includes(q));
    if (activeTab === 'SUBCATS') return subCategories.filter(s => s.name.toLowerCase().includes(q));
    return lyrics.filter(l => l.title.toLowerCase().includes(q) || l.content.toLowerCase().includes(q));
  }, [categories, subCategories, lyrics, activeTab, searchTerm]);

  if (view === 'LOGIN') {
    return (
      <div className="flex flex-col items-center justify-center h-full p-4 animate-fadeIn">
        <h1 className="text-2xl font-bold text-[#5D4037] mb-8 urdu-text">{t.login}</h1>
        <form onSubmit={handleLogin} className="w-full max-w-xs flex flex-col gap-4">
          <input type="text" placeholder={t.username} className="p-3 border border-[#5D4037]/30 bg-white/60 text-center rounded-sm" required />
          <input type="password" placeholder={t.password} className="p-3 border border-[#5D4037]/30 bg-white/60 text-center rounded-sm" required />
          <button type="submit" className="bg-[#5D4037] text-white p-4 font-bold rounded-sm shadow-md">{t.submit}</button>
        </form>
      </div>
    );
  }

  return (
    <div className={`flex flex-col h-full overflow-y-auto pb-10 animate-fadeIn ${lang === 'UR' ? 'text-right' : 'text-left'}`} dir={lang === 'UR' ? 'rtl' : 'ltr'}>
      {/* Header */}
      <div className="flex justify-between items-center mb-6 sticky top-0 bg-[#F5F5DC]/90 backdrop-blur-sm z-30 py-3 border-b border-[#5D4037]/10">
        <button onClick={() => setLang(lang === 'UR' ? 'EN' : 'UR')} className="bg-[#5D4037]/10 text-[#5D4037] text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-tighter">
          {lang === 'UR' ? 'English' : 'اردو'}
        </button>
        <h2 className="text-xl font-bold urdu-text" style={{ color: COLORS.GREEN }}>{t.dashboard}</h2>
        <button onClick={() => { db.logout(); setView('LOGIN'); }} className="text-red-600 text-[10px] font-bold uppercase">{t.logout}</button>
      </div>

      {view === 'DASHBOARD' && (
        <div className="space-y-4">
          {/* Tabs */}
          <div className="flex border border-[#5D4037]/20 rounded-sm overflow-hidden mb-2">
            {(['CATS', 'SUBCATS', 'LYRICS'] as const).map(key => (
              <button 
                key={key} 
                onClick={() => { setActiveTab(key); setSearchTerm(''); }}
                className={`flex-1 py-3 text-[10px] font-bold uppercase transition-colors ${activeTab === key ? 'bg-[#5D4037] text-white' : 'bg-white/40 text-[#5D4037]'}`}
              >
                {key === 'CATS' ? t.categories : key === 'SUBCATS' ? t.subCategories : t.lyrics}
              </button>
            ))}
          </div>

          {/* Search & Actions */}
          <div className="flex gap-2 items-center">
            <input 
              type="text" 
              placeholder={t.search} 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="flex-1 p-2 text-xs border border-[#5D4037]/20 bg-white/40 rounded-sm focus:outline-none focus:border-[#5D4037]" 
            />
            <button 
              onClick={() => setView(activeTab === 'CATS' ? 'CAT_FORM' : activeTab === 'SUBCATS' ? 'SUBCAT_FORM' : 'LYRIC_FORM')}
              className="bg-[#5D4037] text-white text-[10px] font-bold px-4 py-2.5 rounded-sm whitespace-nowrap"
            >
              {activeTab === 'CATS' ? t.addCategory : activeTab === 'SUBCATS' ? t.addSubCategory : t.addLyric}
            </button>
          </div>

          <p className="text-[9px] opacity-40 italic">{t.dragHint}</p>

          <div className="space-y-1.5">
            {filteredData.map((item: any) => (
              <div 
                key={item.id} 
                draggable 
                onDragStart={(e) => onDragStart(e, item.id)}
                onDragOver={(e) => e.preventDefault()}
                onDrop={(e) => onDrop(e, item.id)}
                className="group flex justify-between items-center p-3 bg-white/50 border border-[#5D4037]/5 rounded-sm hover:border-[#5D4037]/20 transition-all cursor-move active:opacity-50"
              >
                <div className="flex items-center gap-1.5">
                   <div className="opacity-30 group-hover:opacity-100 transition-opacity"><GripIcon /></div>
                   <div className="flex gap-1">
                     <button onClick={() => {
                       if (activeTab === 'CATS') { setCatForm(item); setView('CAT_FORM'); }
                       if (activeTab === 'SUBCATS') { setSubCatForm(item); setView('SUBCAT_FORM'); }
                       if (activeTab === 'LYRICS') { setLyricForm(item); setView('LYRIC_FORM'); }
                     }} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-sm"><EditIcon /></button>
                     <button onClick={() => {
                        if (window.confirm(t.confirmDelete(item.name || item.title))) {
                          if (activeTab === 'CATS') db.deleteCategory(item.id);
                          if (activeTab === 'SUBCATS') db.deleteSubCategory(item.id);
                          if (activeTab === 'LYRICS') db.deleteLyric(item.id);
                          refreshData();
                        }
                     }} className="p-1.5 text-red-600 hover:bg-red-50 rounded-sm"><TrashIcon /></button>
                   </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="text-right">
                    <span className={`urdu-text ${activeTab === 'CATS' ? 'font-bold text-lg' : 'text-base'} text-[#5D4037]`}>
                      {item.name || item.title}
                    </span>
                    {item.categoryId && (
                      <div className="text-[9px] opacity-30 uppercase font-bold">
                        {categories.find(c => c.id === item.categoryId)?.name || ''}
                      </div>
                    )}
                  </div>
                  {activeTab === 'CATS' && item.imageUrl && (
                    <img src={item.imageUrl} className="w-10 h-10 object-cover rounded-sm border border-[#5D4037]/10" alt="" />
                  )}
                  <div className="w-6 h-6 rounded-full border border-[#5D4037]/20 flex items-center justify-center text-[9px] font-bold text-[#5D4037]/40">
                    {item.serial}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Forms logic remains consistent but with localization and Image support */}
      {view === 'CAT_FORM' && (
        <div className="flex flex-col gap-6 animate-fadeIn">
          <h3 className="text-xl font-bold urdu-text border-b border-[#5D4037]/10 pb-2">{t.addCategory}</h3>
          <div className="flex flex-col gap-4">
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.name}</label>
              <input value={catForm.name || ''} onChange={e => setCatForm({...catForm, name: e.target.value})} className="p-3 border border-[#5D4037]/30 bg-white/60 rounded-sm" />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.uploadImg}</label>
              <input type="file" accept="image/*" onChange={handleImageUpload} className="text-xs text-[#5D4037]" />
              {catForm.imageUrl && <img src={catForm.imageUrl} className="mt-2 w-full h-32 object-cover rounded-sm border" alt="Preview" />}
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.serial}</label>
              <input type="number" min="1" value={catForm.serial || ''} onChange={e => setCatForm({...catForm, serial: parseInt(e.target.value)})} className="p-3 border border-[#5D4037]/30 bg-white/60 rounded-sm" />
            </div>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setView('DASHBOARD')} className="flex-1 bg-gray-400 text-white p-3 font-bold text-xs uppercase rounded-sm">{t.cancel}</button>
            <button onClick={saveCategory} className="flex-1 bg-[#5D4037] text-white p-3 font-bold text-xs uppercase rounded-sm">{t.save}</button>
          </div>
        </div>
      )}

      {view === 'SUBCAT_FORM' && (
        <div className="flex flex-col gap-6 animate-fadeIn">
          <h3 className="text-xl font-bold urdu-text border-b border-[#5D4037]/10 pb-2">{t.addSubCategory}</h3>
          <div className="flex flex-col gap-4">
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.parentCat}</label>
              <select value={subCatForm.categoryId || ''} onChange={e => setSubCatForm({...subCatForm, categoryId: e.target.value})} className="p-3 border border-[#5D4037]/30 bg-white/60 rounded-sm">
                <option value="">Select Category</option>
                {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.name}</label>
              <input value={subCatForm.name || ''} onChange={e => setSubCatForm({...subCatForm, name: e.target.value})} className="p-3 border border-[#5D4037]/30 bg-white/60 rounded-sm" />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.serial}</label>
              <input type="number" min="1" value={subCatForm.serial || ''} onChange={e => setSubCatForm({...subCatForm, serial: parseInt(e.target.value)})} className="p-3 border border-[#5D4037]/30 bg-white/60 rounded-sm" />
            </div>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setView('DASHBOARD')} className="flex-1 bg-gray-400 text-white p-3 font-bold text-xs uppercase rounded-sm">{t.cancel}</button>
            <button onClick={saveSubCategory} className="flex-1 bg-[#5D4037] text-white p-3 font-bold text-xs uppercase rounded-sm">{t.save}</button>
          </div>
        </div>
      )}

      {view === 'LYRIC_FORM' && (
        <div className="flex flex-col gap-6 animate-fadeIn">
          <h3 className="text-xl font-bold urdu-text border-b border-[#5D4037]/10 pb-2">{t.addLyric}</h3>
          <div className="flex flex-col gap-4">
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.parentCat}</label>
              <select value={selectedParentCatId} onChange={e => setSelectedParentCatId(e.target.value)} className="p-3 border border-[#5D4037]/30 bg-white/60 rounded-sm">
                <option value="">Select Category</option>
                {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.parentSub}</label>
              <select value={lyricForm.subCategoryId || ''} onChange={e => setLyricForm({...lyricForm, subCategoryId: e.target.value})} className="p-3 border border-[#5D4037]/30 bg-white/60 rounded-sm" disabled={!selectedParentCatId}>
                <option value="">Select Sub-Category</option>
                {subCategories.filter(s => s.categoryId === selectedParentCatId).map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.title}</label>
              <input value={lyricForm.title || ''} onChange={e => setLyricForm({...lyricForm, title: e.target.value})} className="p-3 border border-[#5D4037]/30 bg-white/60 rounded-sm" />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.content}</label>
              <textarea value={lyricForm.content || ''} onChange={e => setLyricForm({...lyricForm, content: e.target.value})} className="p-3 border border-[#5D4037]/30 h-40 bg-white/60 rounded-sm" />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-[10px] font-bold opacity-40 uppercase">{t.serial}</label>
              <input type="number" min="1" value={lyricForm.serial || ''} onChange={e => setLyricForm({...lyricForm, serial: parseInt(e.target.value)})} className="p-3 border border-[#5D4037]/30 bg-white/60 rounded-sm" />
            </div>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setView('DASHBOARD')} className="flex-1 bg-gray-400 text-white p-3 font-bold text-xs uppercase rounded-sm">{t.cancel}</button>
            <button onClick={saveLyric} className="flex-1 bg-[#5D4037] text-white p-3 font-bold text-xs uppercase rounded-sm">{t.save}</button>
          </div>
        </div>
      )}
    </div>
  );
};

