            </div>

            <div className="flex items-center gap-2">
              <label className="text-[10px] font-bold opacity-40 uppercase whitespace-nowrap">{t.sortBy}:</label>
              <select 
                value={sortOption} 
                onChange={e => setSortOption(e.target.value as SortOption)}
                className="flex-1 p-1.5 text-[10px] font-bold border border-[#5D4037]/10 bg-white/40 rounded-sm focus:outline-none"
              >
                <option value="SERIAL_ASC">{t.serialAsc}</option>
