          <circle cx="40" cy="40" r="5" fill="none" strokeOpacity="0.2" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#islamicPattern)" />

      <g transform="translate(200, 200)">
        <circle r="90" strokeWidth="0.4" strokeDasharray="5 5" />
