        <text y="12" textAnchor="middle" fontSize="48" className="urdu-text" fill={COLORS.BROWN} stroke="none" opacity="0.7" style={{ fontWeight: 'bold' }}>
          محمد ﷺ
        </text>
        <path d="M-80 -80 L-60 -75 L-75 -60 Z M80 80 L60 75 L75 60 Z" fill={COLORS.BROWN} opacity="0.5" />
