                {sub.imageUrl && (
                  <div className="w-12 h-12 overflow-hidden rounded-sm border border-[#5D4037]/10 shrink-0">
                    <img src={sub.imageUrl} alt={sub.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform" />
                  </div>
                )}
                <span className="text-xl urdu-text text-[#5D4037] font-medium">
                  {sub.name}
