      <div className="rotate-45 border w-1.5 h-1.5" style={{ borderColor: color }}></div>
    </div>
    <div className="h-[0.5px] w-16" style={{ backgroundColor: color }}></div>
  </div>
);

export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [showCalligraphy, setShowCalligraphy] = useState(false);
  const [showLineNumbers, setShowLineNumbers] = useState(false);
  const [copied, setCopied] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [showPlayer, setShowPlayer] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1);
  const [subCategoryLyrics, setSubCategoryLyrics] = useState<Lyric[]>([]);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>(db.getSettings());
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
        setSubCategoryLyrics(db.getLyrics(currentLyric.subCategoryId));
      }
    }
    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current = null;
      }
    };
  }, [id]);

  const { prevLyric, nextLyric } = useMemo(() => {
    if (!lyric || subCategoryLyrics.length === 0) return { prevLyric: null, nextLyric: null };
    const currentIndex = subCategoryLyrics.findIndex(l => l.id === lyric.id);
    return {
      prevLyric: currentIndex > 0 ? subCategoryLyrics[currentIndex - 1] : null,
      nextLyric: currentIndex < subCategoryLyrics.length - 1 ? subCategoryLyrics[currentIndex + 1] : null
    };
  }, [lyric, subCategoryLyrics]);

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  };

  const handleShare = async () => {
    if (!lyric) return;
    const currentUrl = window.location.href;
    const isUrlValid = currentUrl && currentUrl.startsWith('http');
    const textToShare = `${lyric.title}\n\n${lyric.content}`;
    const shareData: ShareData = {
      title: lyric.title,
      text: textToShare,
    };
    if (isUrlValid) {
      shareData.url = currentUrl;
    }
    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        if ((err as Error).name !== 'AbortError') {
          console.warn('Sharing failed with full data, trying text-only:', err);
          try {
            await navigator.share({ text: textToShare });
          } catch (retryErr) {
            console.error('Final share failure:', retryErr);
            handleCopy();
            alert('Sharing failed. Content copied to clipboard instead.');
          }
        }
      }
    } else {
      handleCopy();
      alert('Sharing not supported on this browser. Content copied to clipboard.');
    }
  };

  const formatTime = (time: number) => {
    const min = Math.floor(time / 60);
    const sec = Math.floor(time % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
  };

  const handlePlayPause = () => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.pause();
      } else {
        audioRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = Number(e.target.value);
    if (audioRef.current) {
      audioRef.current.currentTime = time;
      setCurrentTime(time);
    }
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = Number(e.target.value);
    if (audioRef.current) {
      audioRef.current.volume = vol;
      setVolume(vol);
    }
  };

  const onTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
    }
  };

  const onLoadedMetadata = () => {
    if (audioRef.current) {
      setDuration(audioRef.current.duration);
    }
  };

  if (!lyric) return <div className="text-center p-10 urdu-text">کلام نہیں ملا</div>;

  return (
    <div className="flex flex-col items-center w-full h-full text-center relative min-h-[70vh]">
      {/* Top Header Controls */}
      <div className="w-full flex justify-between items-center mb-8 relative z-20 gap-2 overflow-x-auto no-scrollbar py-1">
         <button 
          onClick={() => navigate(`/subcategory/${lyric.subCategoryId}`)}
          className="group flex items-center gap-2 text-[#5D4037] font-bold text-xs hover:opacity-70 transition-all uppercase tracking-widest shrink-0 bg-white/40 px-3 py-1.5 rounded-full border border-[#5D4037]/10"
        >
          <svg className="w-3 h-3 rotate-180 transition-transform group-hover:translate-x-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7"/></svg>
          Back
        </button>

        <div className="flex gap-2">
           {lyric.audioUrl && (
             <button 
               onClick={() => setShowPlayer(!showPlayer)}
               className={`text-[9px] font-bold border border-[#5D4037]/30 px-3 py-1.5 rounded-sm transition-all shadow-sm active:scale-95 flex items-center gap-1 shrink-0 ${
                 showPlayer ? 'bg-[#C62828] text-white' : 'bg-white/80 text-[#5D4037]'
               }`}
             >
               <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M11 5L6 9H2v6h4l5 4V5z"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07"/></svg>
               آڈیو
             </button>
           )}

           <button 
            onClick={() => setShowLineNumbers(!showLineNumbers)}
            className={`text-[9px] font-bold border border-[#5D4037]/30 px-3 py-1.5 rounded-sm transition-all shadow-sm active:scale-95 flex items-center gap-1 shrink-0 ${
              showLineNumbers ? 'bg-[#5D4037] text-white' : 'bg-white/80 text-[#5D4037]'
            }`}
          >
            {showLineNumbers ? 'نمبر ہٹائیں' : 'شمار نمبر'}
          </button>

          <button 
            onClick={() => setShowCalligraphy(!showCalligraphy)}
            className={`text-[9px] font-bold border border-[#5D4037]/30 px-3 py-1.5 rounded-sm transition-all shadow-sm active:scale-95 flex items-center gap-1 shrink-0 ${
              showCalligraphy ? 'bg-[#5D4037] text-white' : 'bg-white/80 text-[#5D4037]'
            }`}
          >
            {showCalligraphy ? 'نقش ہٹائیں' : 'نقش و نگار'}
          </button>

          <button 
            onClick={handleCopy}
            className={`text-[9px] font-bold border border-[#5D4037]/30 px-3 py-1.5 rounded-sm transition-all shadow-sm active:scale-95 flex items-center gap-1 shrink-0 ${
              copied ? 'bg-green-700 text-white' : 'bg-white/80 text-[#5D4037]'
            }`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
            {copied ? 'نقل ہو گیا' : 'نقل کریں'}
          </button>

          <button 
            onClick={handleShare}
            className="text-[9px] font-bold border border-[#5D4037]/30 px-3 py-1.5 rounded-sm transition-all shadow-sm active:scale-95 flex items-center gap-1 shrink-0 bg-white/80 text-[#5D4037]"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
            شیئر کریں
          </button>
        </div>
      </div>

      {/* Custom Audio Player */}
      {showPlayer && lyric.audioUrl && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] w-[85%] max-w-sm bg-white shadow-2xl border border-[#5D4037]/20 rounded-lg p-4 animate-nativeAppTransition">
          <div className="flex items-center justify-between mb-4">
             <div className="flex items-center gap-2 text-[#5D4037]">
               <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M12 3v10.55c-.59-.34-1.27-.55-2-.55-2.21 0-4 1.79-4 4s1.79 4 4 4 4-1.79 4-4V7h4V3h-6z"/></svg>
               <span className="text-[10px] font-bold uppercase tracking-widest opacity-60">Playing Audio</span>
             </div>
             <button onClick={() => setShowPlayer(false)} className="p-1 hover:bg-[#5D4037]/5 rounded-full text-[#5D4037]/40">
                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
             </button>
          </div>

          <div className="flex flex-col gap-3">
            <div className="flex items-center gap-3">
              <button 
                onClick={handlePlayPause}
                className="w-10 h-10 flex items-center justify-center bg-[#5D4037] text-white rounded-full shadow-lg active:scale-90 transition-transform"
              >
                {isPlaying ? (
                  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/></svg>
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
                )}
              </button>

              <div className="flex-1 flex flex-col gap-1">
                <input 
                  type="range" 
                  min="0" 
                  max={duration || 0} 
                  value={currentTime} 
                  onChange={handleSeek}
                  className="w-full h-1.5 bg-[#5D4037]/10 rounded-lg appearance-none cursor-pointer accent-[#5D4037]"
                />
                <div className="flex justify-between text-[8px] font-bold text-[#5D4037]/40 font-sans tracking-tighter">
                  <span>{formatTime(currentTime)}</span>
                  <span>{formatTime(duration)}</span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-2 pt-2 border-t border-[#5D4037]/5">
              <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" className="text-[#5D4037]/30"><path d="M11 5L6 9H2v6h4l5 4V5z"/></svg>
              <input 
                type="range" 
                min="0" 
                max="1" 
                step="0.1" 
                value={volume} 
                onChange={handleVolumeChange}
                className="flex-1 h-1 bg-[#5D4037]/10 rounded-lg appearance-none cursor-pointer accent-[#5D4037]/40"
              />
              <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" className="text-[#5D4037]/30"><path d="M11 5L6 9H2v6h4l5 4V5z"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg>
            </div>
          </div>

          <audio 
            ref={audioRef} 
            src={lyric.audioUrl} 
            onTimeUpdate={onTimeUpdate}
            onLoadedMetadata={onLoadedMetadata}
            onEnded={() => setIsPlaying(false)}
            onPlay={() => setIsPlaying(true)}
            onPause={() => setIsPlaying(false)}
            hidden
          />
        </div>
      )}

      {/* Background Layer */}
      {showCalligraphy && <CalligraphyWatermark color={displaySettings.textColor} />}

      {/* Content Layer */}
      <div className="relative z-10 w-full animate-fadeIn flex-grow flex flex-col items-center">
        <h3 className="text-2xl md:text-3xl font-bold mb-12 urdu-text leading-tight px-4" style={{ color: COLORS.RED }}>
          {lyric.title}
        </h3>

        <div 
          className="flex flex-col items-center w-full urdu-text font-medium px-4 whitespace-pre-wrap"
          style={{ 
            textShadow: '0.4px 0.4px 0.1px rgba(0,0,0,0.05)',
            color: displaySettings.textColor,
            fontSize: `${displaySettings.fontSize}px`,
            lineHeight: displaySettings.lineHeight
          }}
        >
          {lyric.content.split('\n').map((line, i) => (
             <React.Fragment key={i}>
               <div className="w-full flex items-center justify-center group relative min-h-[3rem]">
                 {showLineNumbers && (
                   <span 
                    className="absolute -right-4 top-1 text-[10px] font-bold font-sans tracking-tighter opacity-70 group-hover:opacity-100 transition-opacity"
                    style={{ color: displaySettings.textColor }}
                   >
                     {(i + 1).toString().padStart(2, '0')}
                   </span>
                 )}
                 <div className="flex-grow text-center px-2">
                   {line}
                 </div>
               </div>
               {i < lyric.content.split('\n').length - 1 && <LineDivider color={displaySettings.textColor} />}
             </React.Fragment>
          ))}
        </div>
      </div>

      {/* Sequential Navigation Controls */}
      <div className="w-full grid grid-cols-2 gap-4 mt-16 mb-6 relative z-20">
        <button
          disabled={!nextLyric}
          onClick={() => nextLyric && navigate(`/lyric/${nextLyric.id}`)}
          className={`urdu-text py-4 border border-[#5D4037]/40 text-[#5D4037] font-bold text-lg transition-all active:scale-95 flex items-center justify-center gap-3 group shadow-sm bg-white/40 backdrop-blur-sm rounded-sm ${!nextLyric ? 'opacity-10 cursor-not-allowed border-transparent shadow-none' : 'hover:bg-[#5D4037] hover:text-[#F5F5DC] hover:scale-[1.02] hover:shadow-md hover:border-[#5D4037]'}`}
        >
          <svg className="w-5 h-5 transition-transform group-hover:-translate-x-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7"/></svg>
          اگلا کلام
        </button>
        <button
          disabled={!prevLyric}
          onClick={() => prevLyric && navigate(`/lyric/${prevLyric.id}`)}
          className={`urdu-text py-4 border border-[#5D4037]/40 text-[#5D4037] font-bold text-lg transition-all active:scale-95 flex items-center justify-center gap-3 group shadow-sm bg-white/40 backdrop-blur-sm rounded-sm ${!prevLyric ? 'opacity-10 cursor-not-allowed border-transparent shadow-none' : 'hover:bg-[#5D4037] hover:text-[#F5F5DC] hover:scale-[1.02] hover:shadow-md hover:border-[#5D4037]'}`}
        >
          پچھلا کلام
          <svg className="w-5 h-5 transition-transform group-hover:translate-x-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7"/></svg>
        </button>
      </div>

      {/* Information Footer */}
      <div className="mt-4 pt-6 border-t border-[#5D4037]/10 w-full flex justify-between items-center px-4 relative z-10 mb-4">
        <div className="flex flex-col items-start">
          <span className="text-[9px] font-bold opacity-30 uppercase tracking-widest leading-none mb-1">Position</span>
          <span className="text-xs font-bold text-[#5D4037]/70 leading-none">
            {subCategoryLyrics.findIndex(l => l.id === lyric.id) + 1} / {subCategoryLyrics.length}
          </span>
        </div>
        <div className="flex flex-col items-end">
          <span className="text-[9px] font-bold opacity-30 uppercase tracking-widest leading-none mb-1">Serial</span>
          <span className="text-xs font-bold text-[#5D4037]/70 leading-none">{lyric.serial}</span>
        </div>
      </div>
    </div>
  );
};

