export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [showLineNumbers, setShowLineNumbers] = useState(false);
  const [copied, setCopied] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [showPlayer, setShowPlayer] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [subCategoryLyrics, setSubCategoryLyrics] = useState<Lyric[]>([]);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>(db.getSettings());
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const scrollContainerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
        setSubCategoryLyrics(db.getLyrics(currentLyric.subCategoryId));
      }
    }
  }, [id]);

  useEffect(() => {
    // Reset scroll to top when lyric changes
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollTo(0, 0);
    }
  }, [id]);

  const { prevLyric, nextLyric } = useMemo(() => {
    if (!lyric || subCategoryLyrics.length === 0) return { prevLyric: null, nextLyric: null };
    const currentIndex = subCategoryLyrics.findIndex(l => l.id === lyric.id);
    return {
      prevLyric: currentIndex > 0 ? subCategoryLyrics[currentIndex - 1] : null,
      nextLyric: currentIndex < subCategoryLyrics.length - 1 ? subCategoryLyrics[currentIndex + 1] : null
    };
  }, [lyric, subCategoryLyrics]);

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  };

  const handleShare = async () => {
    if (!lyric) return;
    const textToShare = `${lyric.title}\n\n${lyric.content}`;
    if (navigator.share) {
      try { await navigator.share({ title: lyric.title, text: textToShare }); }
      catch (err) { handleCopy(); }
    } else { handleCopy(); }
  };

  const handlePlayPause = () => {
    if (audioRef.current) {
      isPlaying ? audioRef.current.pause() : audioRef.current.play();
      setIsPlaying(!isPlaying);
    }
  };

  if (!lyric) return <div className="text-center p-10 urdu-text">کلام نہیں ملا</div>;

  return (
    <div 
      className="flex flex-col w-full h-full relative p-1 overflow-hidden animate-fadeIn"
      style={{ backgroundColor: displaySettings.backgroundColor }}
    >
      {/* Outer CorelDRAW Frame Border */}
      <div className="absolute inset-2 border-[12px] border-[#5D4037] pointer-events-none z-50">
        <div className="absolute -inset-[2px] border border-white opacity-20"></div>
        <div className="absolute inset-[4px] border border-white opacity-20"></div>
        {/* Corners motifs */}
        <div className="absolute top-0 left-0 w-8 h-8 bg-[#5D4037] border-r-4 border-b-4 border-white/20"></div>
        <div className="absolute top-0 right-0 w-8 h-8 bg-[#5D4037] border-l-4 border-b-4 border-white/20"></div>
        <div className="absolute bottom-0 left-0 w-8 h-8 bg-[#5D4037] border-r-4 border-t-4 border-white/20"></div>
        <div className="absolute bottom-0 right-0 w-8 h-8 bg-[#5D4037] border-l-4 border-t-4 border-white/20"></div>
      </div>

      {/* Top Controls Bar - Mimicking first image tabs */}
      <div className="relative z-[60] mt-5 px-6 flex justify-center gap-1">
        <button 
          onClick={handleShare}
          className="bg-[#5D4037] text-white urdu-text text-[10px] px-3 py-1.5 border border-white/30 rounded-t-lg shadow-md active:scale-95 flex items-center gap-1"
        >
          <svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><path d="M18 16.08c-.76 0-1.44.3-1.96.77L8.91 12.7c.05-.23.09-.46.09-.7s-.04-.47-.09-.7l7.05-4.11c.54.5 1.25.81 2.04.81 1.66 0 3-1.34 3-3s-1.34-3-3-3-3 1.34-3 3c0 .24.04.47.09.7L8.04 9.81C7.5 9.31 6.79 9 6 9c-1.66 0-3 1.34-3 3s1.34 3 3 3c.79 0 1.5-.31 2.04-.81l7.12 4.16c-.05.21-.08.43-.08.65 0 1.61 1.31 2.92 2.92 2.92 1.61 0 2.92-1.31 2.92-2.92s-1.31-2.92-2.92-2.92z"/></svg>
          شیئر کریں
        </button>
        <button 
          onClick={handleCopy}
          className="bg-[#5D4037] text-white urdu-text text-[10px] px-3 py-1.5 border border-white/30 rounded-t-lg shadow-md active:scale-95 flex items-center gap-1"
        >
          {copied ? 'کاپی ہوا' : 'نقل کریں'}
        </button>
        <button 
          onClick={() => setShowLineNumbers(!showLineNumbers)}
          className="bg-[#5D4037] text-white urdu-text text-[10px] px-3 py-1.5 border border-white/30 rounded-t-lg shadow-md active:scale-95"
        >
          {showLineNumbers ? 'نمبر ہٹائیں' : 'شمار نمبر'}
        </button>
        <button 
          onClick={() => navigate(`/subcategory/${lyric.subCategoryId}`)}
          className="bg-[#5D4037] text-white urdu-text text-[10px] px-4 py-1.5 border border-white/30 rounded-t-lg shadow-md active:scale-95 font-bold uppercase tracking-widest"
        >
          BACK
        </button>
      </div>

      {/* Main Inner Scrollable Content Area */}
      <div 
        ref={scrollContainerRef}
        className="flex-grow overflow-y-auto z-10 mx-6 mb-6 px-4 pt-4 custom-scroll"
        style={{ 
          color: displaySettings.textColor,
          scrollbarWidth: 'none'
        }}
      >
        <div className="flex flex-col items-center min-h-full pb-20">
          <SealLogo color={displaySettings.textColor} />

          <h1 
            className="text-2xl md:text-3xl font-bold urdu-text text-center mb-10 px-4 leading-relaxed"
            style={{ color: COLORS.RED }}
          >
            {lyric.title}
          </h1>

          <div 
            className="w-full urdu-text text-center whitespace-pre-wrap flex flex-col items-center"
            style={{ 
              fontSize: `${displaySettings.fontSize}px`,
              lineHeight: displaySettings.lineHeight
            }}
          >
            {lyric.content.split('\n').map((line, i) => (
              <React.Fragment key={i}>
                <div className="relative w-full group py-2">
                  {showLineNumbers && (
                    <span className="absolute -right-2 top-1/2 -translate-y-1/2 text-[10px] opacity-30 font-sans">
                      {(i + 1).toString().padStart(2, '0')}
                    </span>
                  )}
                  <span className="inline-block px-2">{line}</span>
                </div>
                {i < lyric.content.split('\n').length - 1 && i % 2 === 1 && <LineDivider color={displaySettings.textColor} />}
              </React.Fragment>
            ))}
          </div>

          {/* Sequential Navigation inside scroll for easy reach */}
          <div className="w-full flex justify-between mt-16 mb-10 px-2 gap-4">
             <button
              disabled={!nextLyric}
              onClick={() => nextLyric && navigate(`/lyric/${nextLyric.id}`)}
              className={`flex-1 urdu-text py-3 border border-[#5D4037] rounded transition-all flex items-center justify-center gap-2 ${!nextLyric ? 'opacity-20' : 'active:bg-[#5D4037]/10'}`}
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7"/></svg>
              اگلا کلام
            </button>
            <button
              disabled={!prevLyric}
              onClick={() => prevLyric && navigate(`/lyric/${prevLyric.id}`)}
              className={`flex-1 urdu-text py-3 border border-[#5D4037] rounded transition-all flex items-center justify-center gap-2 ${!prevLyric ? 'opacity-20' : 'active:bg-[#5D4037]/10'}`}
            >
              پچھلا کلام
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7"/></svg>
            </button>
          </div>
        </div>
      </div>

      {/* Persistent Audio Trigger */}
      {lyric.audioUrl && (
        <button 
          onClick={handlePlayPause}
          className="fixed bottom-10 right-10 z-[70] w-12 h-12 bg-[#5D4037] text-white rounded-full shadow-2xl flex items-center justify-center active:scale-90 transition-transform border-2 border-white/20"
        >
          {isPlaying ? (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/></svg>
          ) : (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
          )}
        </button>
      )}

      {lyric.audioUrl && <audio ref={audioRef} src={lyric.audioUrl} onEnded={() => setIsPlaying(false)} hidden />}

      <style>{`
        .custom-scroll::-webkit-scrollbar { width: 0px; background: transparent; }
        .custom-scroll { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

