  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
        // Correctly fetch lyrics for navigation within the same subcategory
        const filtered = allLyrics.filter(l => l.subCategoryId === currentLyric.subCategoryId)
                                 .sort((a, b) => a.serial - b.serial);
        setSubCategoryLyrics(filtered);
      }
    }
  }, [id]);

  useEffect(() => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollTo({ top: 0, behavior: 'instant' });
    }
  }, [id]);

  const { currentIndex, nextLyric, prevLyric } = useMemo(() => {
    if (!lyric || subCategoryLyrics.length === 0) return { currentIndex: -1, nextLyric: null, prevLyric: null };
    const idx = subCategoryLyrics.findIndex(l => l.id === lyric.id);
    return {
      currentIndex: idx,
      nextLyric: idx < subCategoryLyrics.length - 1 ? subCategoryLyrics[idx + 1] : null,
      prevLyric: idx > 0 ? subCategoryLyrics[idx - 1] : null
    };
  }, [lyric, subCategoryLyrics]);

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
