              <React.Fragment key={i}>
                <div className="relative w-full py-2 group">
                  {showLineNumbers && (
                    <span className="absolute -right-6 top-1/2 -translate-y-1/2 text-[10px] opacity-20 font-sans select-none tracking-tighter">
