            ))}
          </div>

          {/* Sequential Footer Navigation inside scroll for UX */}
          <div className="w-full mt-24 mb-10 flex gap-4">
            <button
              onClick={() => nextLyric && navigate(`/lyric/${nextLyric.id}`)}
              disabled={!nextLyric}
              className="flex-1 urdu-text py-4 border border-[#5D4037]/20 rounded bg-white/40 active:bg-[#5D4037]/10 transition-all disabled:opacity-10 flex items-center justify-center gap-2 text-[#5D4037] font-bold"
