        setLyric(currentLyric);
        const filtered = allLyrics.filter(l => l.subCategoryId === currentLyric.subCategoryId)
                                 .sort((a, b) => a.serial - b.serial);
        setSubCategoryLyrics(filtered);
      }
    }
  }, [id]);

  useEffect(() => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollTo({ top: 0, behavior: 'instant' });
    }
  }, [id]);

  const { nextLyric, prevLyric } = useMemo(() => {
