import { COLORS } from '../constants';

const QURAN_LOGO = "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Quran_kareem_orange_logo.png/1014px-Quran_kareem_orange_logo.png";

export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [copied, setCopied] = useState(false);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>(db.getSettings());
  const scrollContainerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
      }
    }
  }, [id]);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [id]);

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  };

  const handleShare = async () => {
    if (!lyric) return;
    const textToShare = `${lyric.title}\n\n${lyric.content}`;
    if (navigator.share) {
      try { await navigator.share({ title: lyric.title, text: textToShare }); }
      catch (err) { handleCopy(); }
    } else { handleCopy(); }
  };

  if (!lyric) return <div className="text-center p-10 urdu-text">کلام نہیں ملا</div>;

  return (
    <div className="flex flex-col w-full min-h-full pb-20 animate-fadeIn" style={{ backgroundColor: displaySettings.backgroundColor }}>
