        <div className="flex gap-4">
          <button onClick={handleShare} className="text-[#5D4037] opacity-60 hover:opacity-100">
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
          </button>
          <button onClick={handleCopy} className="text-[#5D4037] opacity-60 hover:opacity-100">
            {copied ? <span className="text-[10px] font-bold text-green-700">Copied!</span> : <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>}
          </button>
        </div>
      </div>

      <div className="flex flex-col items-center px-6 py-10 w-full max-w-lg mx-auto">
        {/* Quran Logo */}
        <div className="mb-8">
          <img src={QURAN_LOGO} alt="Quran Logo" className="w-24 h-24 object-contain" />
        </div>

        {/* Title */}
        <h1 className="text-3xl font-bold urdu-text text-center mb-12 leading-relaxed" style={{ color: COLORS.RED }}>
          {lyric.title}
        </h1>

        {/* Content */}
        <div 
          className="w-full urdu-text text-center whitespace-pre-wrap"
          style={{ 
            color: displaySettings.textColor,
            fontSize: `${displaySettings.fontSize}px`,
            lineHeight: displaySettings.lineHeight
          }}
        >
          {lyric.content}
        </div>
      </div>
    </div>
  );
};

