import React, { useEffect, useState, useMemo, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../db';
import { Lyric, DisplaySettings } from '../types';
import { COLORS } from '../constants';

const QURAN_LOGO = "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Quran_kareem_orange_logo.png/1014px-Quran_kareem_orange_logo.png";

export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [copied, setCopied] = useState(false);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>(db.getSettings());
  const scrollContainerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
      }
    }
  }, [id]);

  useEffect(() => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollTo(0, 0);
    }
  }, [id]);

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  };

  const handleShare = async () => {
    if (!lyric) return;
    const textToShare = `${lyric.title}\n\n${lyric.content}`;
    if (navigator.share) {
      try { await navigator.share({ title: lyric.title, text: textToShare }); }
      catch (err) { handleCopy(); }
    } else { handleCopy(); }
  };

  if (!lyric) return <div className="text-center p-10 urdu-text h-full flex items-center justify-center">کلام نہیں ملا</div>;

  return (
    <div className="flex flex-col w-full h-full relative overflow-hidden animate-fadeIn" style={{ backgroundColor: displaySettings.backgroundColor }}>
      {/* Ornamental Fixed Frame */}
      <div className="absolute inset-2 border-[10px] border-[#5D4037] pointer-events-none z-[80]">
        <div className="absolute top-0 left-0 w-8 h-8 bg-[#5D4037] border-r border-b border-white/20"></div>
        <div className="absolute top-0 right-0 w-8 h-8 bg-[#5D4037] border-l border-b border-white/20"></div>
        <div className="absolute bottom-0 left-0 w-8 h-8 bg-[#5D4037] border-r border-t border-white/20"></div>
        <div className="absolute bottom-0 right-0 w-8 h-8 bg-[#5D4037] border-l border-t border-white/20"></div>

        {/* Side Motifs */}
        <div className="absolute top-1/2 -left-3 -translate-y-1/2 w-4 h-24 bg-[#5D4037] rounded-full border border-white/10"></div>
        <div className="absolute top-1/2 -right-3 -translate-y-1/2 w-4 h-24 bg-[#5D4037] rounded-full border border-white/10"></div>
      </div>

      {/* Top Header Controls - Fixed */}
      <div className="relative z-[90] mt-[24px] mx-[22px]">
        <div className="bg-[#5D4037] h-10 w-full flex items-center justify-between px-4 rounded-t-sm shadow-md">
          <button onClick={() => navigate(-1)} className="text-white text-[10px] font-bold uppercase tracking-widest px-2 py-1 border border-white/20 rounded">Back</button>
          <div className="flex gap-4">
            <button onClick={handleShare} className="text-white/80 hover:text-white transition-colors">
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
            </button>
            <button onClick={handleCopy} className="text-white/80 hover:text-white transition-colors">
              {copied ? <span className="text-[10px] font-bold text-white">Copied!</span> : <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>}
            </button>
          </div>
        </div>
      </div>

      {/* Internal Scrollable Content Area */}
      <div 
        ref={scrollContainerRef}
        className="flex-grow overflow-y-auto z-10 mx-[30px] mb-[30px] mt-0 px-6 pt-10 pb-20 custom-scroll relative"
        style={{ color: displaySettings.textColor }}
      >
        <div className="flex flex-col items-center min-h-full">
          {/* Quran Logo */}
          <div className="mb-8">
            <img src={QURAN_LOGO} alt="Quran Logo" className="w-24 h-24 object-contain" />
          </div>

          {/* Title Area */}
          <div className="w-full text-center mb-12">
            <h1 
              className="text-3xl md:text-4xl font-bold urdu-text leading-[1.8] px-4"
              style={{ color: COLORS.RED }}
            >
              {lyric.title}
            </h1>
            <div className="w-24 h-0.5 bg-[#5D4037]/20 mx-auto mt-4"></div>
          </div>

          {/* Verses */}
          <div 
            className="w-full urdu-text text-center whitespace-pre-wrap flex flex-col items-center"
            style={{ 
              fontSize: `${displaySettings.fontSize}px`,
              lineHeight: displaySettings.lineHeight
            }}
          >
            {lyric.content}
          </div>
        </div>
      </div>

      <style>{`
        .custom-scroll::-webkit-scrollbar { width: 0px; background: transparent; }
        .custom-scroll { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

