import React, { useEffect, useState, useMemo, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../db';
import { Lyric, DisplaySettings } from '../types';
import { COLORS } from '../constants';

const QURAN_LOGO = "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Quran_kareem_orange_logo.png/1014px-Quran_kareem_orange_logo.png";

const TabButton: React.FC<{ onClick: () => void; label: string; icon?: React.ReactNode }> = ({ onClick, label, icon }) => (
  <button 
    onClick={onClick}
    className="px-3 py-1 bg-[#FDF9EA] text-[#5D4037] text-[10px] font-bold urdu-text rounded-t border-x border-t border-[#5D4037]/20 flex items-center gap-1 active:bg-[#5D4037] active:text-white transition-all shadow-sm"
  >
    {icon}
    {label}
  </button>
);

const LineDivider: React.FC<{ color: string }> = ({ color }) => (
  <div className="flex items-center justify-center w-full my-6 opacity-10 select-none pointer-events-none">
    <div className="h-[0.5px] w-12" style={{ backgroundColor: color }}></div>
    <div className="mx-3 rotate-45 border w-1.5 h-1.5" style={{ borderColor: color }}></div>
