export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [copied, setCopied] = useState(false);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>(db.getSettings());
  const scrollContainerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
      }
    }
  }, [id]);

  useEffect(() => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollTo(0, 0);
    }
  }, [id]);

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  };

  const handleShare = async () => {
    if (!lyric) return;
    const textToShare = `${lyric.title}\n\n${lyric.content}`;
    if (navigator.share) {
      try { await navigator.share({ title: lyric.title, text: textToShare }); }
      catch (err) { handleCopy(); }
    } else { handleCopy(); }
  };

  if (!lyric) return <div className="text-center p-10 urdu-text h-full flex items-center justify-center">کلام نہیں ملا</div>;

  return (
    <div className="flex flex-col w-full h-full relative overflow-hidden animate-fadeIn" style={{ backgroundColor: displaySettings.backgroundColor }}>
      {/* Fixed Ornamental Frame */}
      <div className="absolute inset-2 border-[10px] border-[#5D4037] pointer-events-none z-[80]">
        <div className="absolute top-0 left-0 w-8 h-8 bg-[#5D4037] border-r border-b border-white/20"></div>
        <div className="absolute top-0 right-0 w-8 h-8 bg-[#5D4037] border-l border-b border-white/20"></div>
        <div className="absolute bottom-0 left-0 w-8 h-8 bg-[#5D4037] border-r border-t border-white/20"></div>
        <div className="absolute bottom-0 right-0 w-8 h-8 bg-[#5D4037] border-l border-t border-white/20"></div>
        <div className="absolute top-1/2 -left-3 -translate-y-1/2 w-4 h-24 bg-[#5D4037] rounded-full border border-white/10"></div>
        <div className="absolute top-1/2 -right-3 -translate-y-1/2 w-4 h-24 bg-[#5D4037] rounded-full border border-white/10"></div>
      </div>

      {/* Fixed Top Tab Bar */}
      <div className="relative z-[90] mt-[24px] mx-[22px]">
        <div className="bg-[#5D4037] h-6 w-full px-4 rounded-t-sm shadow-md"></div>
        <div className="flex justify-center items-end gap-1.5 -mt-4.5 h-8">
          <TabButton onClick={() => navigate(-1)} label="BACK" />
          <TabButton onClick={handleShare} label="SHARE" icon={<svg width="8" height="8" viewBox="0 0 24 24" fill="currentColor"><path d="M18 16.08c-.76 0-1.44.3-1.96.77L8.91 12.7c.05-.23.09-.46.09-.7s-.04-.47-.09-.7l7.05-4.11c.54.5 1.25.81 2.04.81 1.66 0 3-1.34 3-3s-1.34-3-3-3-3 1.34-3 3c0 .24.04.47.09.7L8.04 9.81C7.5 9.31 6.79 9 6 9c-1.66 0-3 1.34-3 3s1.34 3 3 3c.79 0 1.5-.31 2.04-.81l7.12 4.16c-.05.21-.08.43-.08.65 0 1.61 1.31 2.92 2.92 2.92 1.61 0 2.92-1.31 2.92-2.92s-1.31-2.92-2.92-2.92z"/></svg>} />
          <TabButton onClick={handleCopy} label={copied ? "COPIED" : "COPY"} />
        </div>
      </div>

      {/* Internal Scroll Content */}
      <div 
        ref={scrollContainerRef}
        className="flex-grow overflow-y-auto z-10 mx-[30px] mb-[30px] mt-2 px-6 pt-8 pb-16 custom-scroll-poetry relative"
        style={{ color: displaySettings.textColor }}
      >
        <div className="flex flex-col items-center min-h-full">
          {/* Quran Logo */}
          <div className="mb-8 p-2 bg-white/10 rounded-full border border-[#5D4037]/5">
            <img src={QURAN_LOGO} alt="Quran Logo" className="w-24 h-24 object-contain" />
          </div>

          {/* Poetry Title */}
          <div className="w-full text-center mb-12">
            <h1 
              className="text-3xl font-bold urdu-text leading-tight px-2"
              style={{ color: COLORS.RED }}
            >
              {lyric.title}
            </h1>
            <div className="w-16 h-0.5 bg-[#5D4037]/20 mx-auto mt-4"></div>
          </div>

          {/* Verses */}
          <div 
            className="w-full urdu-text text-center whitespace-pre-wrap flex flex-col items-center"
            style={{ 
              fontSize: `${displaySettings.fontSize}px`,
              lineHeight: displaySettings.lineHeight
            }}
          >
            {lyric.content.split('\n').map((line, i) => (
              <React.Fragment key={i}>
                <div className="w-full py-1.5">{line}</div>
                {i < lyric.content.split('\n').length - 1 && i % 2 === 1 && <LineDivider color={displaySettings.textColor} />}
              </React.Fragment>
            ))}
          </div>

          <div className="mt-16 opacity-30 text-[10px] tracking-widest font-bold">Kalam-e-Raza Digital</div>
        </div>
      </div>

      <style>{`
        .custom-scroll-poetry::-webkit-scrollbar { width: 0px; background: transparent; }
        .custom-scroll-poetry { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

